<script setup lang="ts">
import {ref,computed,watch} from 'vue';
import {control,currentMember,canManageMembers,controlCommand,invitationProof} from '../services/control';
import type {Model} from '../../../../packages/api-client/src/control';
import Modal from './Modal.vue';import Icon from './Icon.vue';
defineProps<{manage?:boolean;page?:boolean}>();
const dialog=ref(''),selected=ref<Model<'Member'>>(),invite=ref<Model<'Invitation'>>(),destination=ref(''),access=ref('member'),days=ref(7),reason=ref(''),error=ref(''),busy=ref(false),proof=ref(''),createdId=ref('');
const decision=ref<Model<'MembershipDecision'>>();const choice=ref('approve');
const operationKey=ref('');
function open(kind:string,member?:Model<'Member'>,invitation?:Model<'Invitation'>){dialog.value=kind;selected.value=member;invite.value=invitation;error.value='';reason.value='';proof.value='';operationKey.value=crypto.randomUUID();}
watch(()=>control.workspace?.id,()=>{dialog.value='';proof.value='';});
const actionable=computed(()=>control.commands.includes(dialog.value==='invite'?'member.invite':dialog.value==='decision'?'decision.respond':dialog.value==='transfer'?'workspace.request-owner-transfer':dialog.value==='access'?'member.request-access-change':dialog.value==='revoke'?'invitation.revoke':dialog.value==='leave'?'member.leave':'member.remove'));
async function submit(){busy.value=true;error.value='';try{
 if(dialog.value==='invite'){
  const result=await controlCommand('member.invite',{destination:destination.value.trim(),requested_role:access.value,expires_at:new Date(Date.now()+days.value*86400000).toISOString()},[],operationKey.value);
  createdId.value=result.result_refs[0]!.id;dialog.value='proof';proof.value=await invitationProof(createdId.value);
 }else if(dialog.value==='decision'){
  const item=decision.value!;await controlCommand('decision.respond',{decision_id:item.id,decision_revision:item.revision,choice_id:choice.value,subject_versions:item.subject_versions},[],operationKey.value);dialog.value='';
 }else if(dialog.value==='access'||dialog.value==='transfer'){
  const item=selected.value!;await controlCommand(dialog.value==='transfer'?'workspace.request-owner-transfer':'member.request-access-change',dialog.value==='transfer'?{recipient_member_id:item.id,expires_at:new Date(Date.now()+7*86400000).toISOString()}:{member_id:item.id,requested_access:access.value,expires_at:new Date(Date.now()+7*86400000).toISOString()},[{kind:'membership',id:item.id,revision:item.revision}],operationKey.value);dialog.value='';
 }else if(dialog.value==='revoke'){
  const item=invite.value!;await controlCommand('invitation.revoke',{invitation_id:item.id,reason:reason.value},[{kind:'invitation',id:item.id,revision:item.revision}],operationKey.value);dialog.value='';
 }else{
  const item=selected.value!;await controlCommand(dialog.value==='leave'?'member.leave':'member.remove',dialog.value==='leave'?{}:{member_id:item.id,reason:reason.value},[{kind:'membership',id:item.id,revision:item.revision}],operationKey.value);dialog.value='';
 }
 }catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function showProof(item:Model<'Invitation'>){open('proof');createdId.value=item.id;try{proof.value=await invitationProof(item.id);}catch(e){error.value=(e as Error).message;}}
</script>
<template>
<section class="members-surface" :class="{'colleagues-page':page}">
 <div class="members-intro"><p>{{page?'Open a colleague to see their work in this workspace.':manage?'Manage access to this workspace.':'Open a colleague to see their membership in this workspace.'}}</p><button v-if="manage&&canManageMembers" class="button primary" :disabled="!control.commands.includes('member.invite')" @click="open('invite')"><Icon name="plus"/>Invite member</button></div>
 <div v-if="!control.active" class="small-empty"><Icon name="users" :size="22"/><p>No colleagues yet</p><RouterLink to="/settings?tab=connection" class="text-button">Connect to manage colleagues</RouterLink></div>
 <div class="member-list"><button v-for="member in control.members" :key="member.id" @click="open('detail',member)"><span class="workspace-avatar">{{member.display_name[0]?.toUpperCase()}}</span><span>{{member.display_name}}<small>{{member.access_role}}{{member.user_id===control.session?.user_id?' · You':''}}</small></span></button></div>
 <template v-if="manage&&control.decisions.length"><h3>Access decisions</h3><div v-for="item in control.decisions" :key="item.id" class="invitation-row"><span>{{item.action==='transfer-owner'?'Transfer ownership':'Change access'}} · {{control.members.find(m=>m.id===item.member_id)?.display_name||item.member_id}}<small>{{item.requested_role}} · {{item.state}} · Expires {{new Date(item.expires_at).toLocaleString()}}</small></span><button v-if="item.state==='pending'&&item.responder_id===control.session?.user_id" class="button" @click="open('decision');decision=item;choice='approve'">Respond</button></div></template>
 <template v-if="manage&&canManageMembers"><h3>Invitations</h3><p v-if="!control.invitations.length" class="muted">No invitations yet</p><div v-for="item in control.invitations" :key="item.id" class="invitation-row"><span>{{item.recipient}}<small>{{item.requested_role}} · {{item.state}}</small></span><template v-if="item.state==='pending'"><button class="text-button" @click="showProof(item)">View proof</button><button class="text-button" @click="open('revoke',undefined,item)">Revoke</button></template></div></template>
 <template v-if="manage&&control.active"><h3>Leave workspace</h3><div class="leave-row"><p>{{currentMember?.access_role==='owner'?'Transfer ownership before leaving this workspace.':'Leaving removes your access. Your contributions remain attributed to you.'}}</p><button class="button" :disabled="currentMember?.access_role==='owner'||!control.commands.includes('member.leave')" @click="open('leave',currentMember)">Leave workspace</button></div></template>
 <Modal v-if="dialog" :title="dialog==='invite'?'Invite member':dialog==='proof'?'Invitation proof':dialog==='decision'?'Access decision':dialog==='transfer'?'Transfer ownership':dialog==='access'?'Change access':dialog==='detail'?'Workspace member':dialog==='revoke'?'Revoke invitation':dialog==='leave'?'Leave workspace':'Remove member'" @close="!busy&&(dialog='')">
  <form class="member-dialog" @submit.prevent="submit">
   <header><h2>{{dialog==='invite'?'Invite member':dialog==='proof'?'Invitation proof':dialog==='decision'?'Access decision':dialog==='transfer'?'Transfer ownership':dialog==='access'?'Change access':dialog==='detail'?selected?.display_name:dialog==='revoke'?'Revoke invitation':dialog==='leave'?'Leave workspace':'Remove member'}}</h2><button type="button" class="icon-button" aria-label="Close" :disabled="busy" @click="dialog=''"><Icon name="close"/></button></header>
   <template v-if="dialog==='invite'"><p>Use the recipient’s installation account ID. Share the proof with them privately; no email is sent.</p><label>Account ID<input v-model="destination" pattern="[a-z][a-z0-9_-]{2,127}" required autofocus/></label><label>Access<select v-model="access"><option value="member">Member</option><option value="viewer">Viewer</option><option v-if="currentMember?.access_role==='owner'" value="admin">Administrator</option></select></label><label>Expires in days<input v-model.number="days" type="number" min="1" max="30" required/></label></template>
   <template v-else-if="dialog==='proof'"><p>This proof works only for the invited account. It expires at the invitation deadline.</p><label>Invitation ID<input :value="createdId" readonly/></label><label>Proof<input :value="proof" readonly autocomplete="off"/></label></template>
   <template v-else-if="dialog==='detail'"><p>{{selected?.access_role}} · {{selected?.user_id}}</p><p>Research activity will appear when the inquiry service is available.</p><template v-if="manage&&canManageMembers&&selected?.access_role!=='owner'"><button v-if="currentMember?.access_role==='owner'||selected?.access_role!=='admin'" type="button" class="button" @click="open('access',selected);access=selected?.access_role??'member'">Change access</button><button v-if="currentMember?.access_role==='owner'" type="button" class="button" @click="open('transfer',selected)">Transfer ownership</button></template><button v-if="manage&&canManageMembers&&selected?.access_role!=='owner'&&(currentMember?.access_role==='owner'||selected?.access_role!=='admin')" type="button" class="button" @click="open('remove',selected)">Remove member</button></template>
   <template v-else-if="dialog==='access'||dialog==='transfer'"><p>{{dialog==='transfer'?'The recipient must accept this exact request before ownership changes. You will become an administrator.':'This creates a structured decision. Confirm the exact change separately before access changes.'}} Requests expire in seven days.</p><label v-if="dialog==='access'">Access<select v-model="access"><option value="member">Member</option><option value="viewer">Viewer</option><option v-if="currentMember?.access_role==='owner'" value="admin">Administrator</option></select></label></template>
   <template v-else-if="dialog==='decision'"><p><strong>{{control.members.find(m=>m.id===decision?.member_id)?.display_name||decision?.member_id}}</strong></p><p>{{decision?.action==='transfer-owner'?'Accept ownership of this workspace? The current owner will become an administrator.':'Approve the requested access change?'}} Target role: {{decision?.requested_role}}.</p><p>The approval applies only to the displayed request and its pinned versions. Changes since the request require a new decision.</p><label>Response<select v-model="choice"><option value="approve">Approve</option><option value="reject">Reject</option></select></label></template>
   <template v-else><p>{{dialog==='leave'?'You will lose access to this workspace. Contributions and their attribution are preserved.':dialog==='remove'?'This member will lose access immediately. Their contributions remain in the workspace.':'The recipient will no longer be able to accept this invitation.'}}</p><label v-if="dialog!=='leave'">Reason<textarea v-model="reason" maxlength="10000" required autofocus/></label></template>
   <p v-if="error" class="form-error" role="alert">{{error}}</p>
   <footer><button type="button" class="button" :disabled="busy" @click="dialog=''">{{['detail','proof'].includes(dialog)?'Close':'Cancel'}}</button><button v-if="!['detail','proof'].includes(dialog)" class="button primary" :disabled="busy||!actionable">{{busy?'Saving…':dialog==='invite'?'Create invitation':'Confirm'}}</button></footer>
  </form>
 </Modal>
</section>
</template>
<style scoped>
.members-intro{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:24px}.members-intro p,.muted,.leave-row p{font-size:14px;line-height:22px;color:var(--muted)}.member-list{display:flex;gap:12px;flex-wrap:wrap}.member-list>button{display:flex;gap:12px;align-items:center;border:1px solid var(--border);border-radius:8px;padding:14px 16px;min-width:260px;text-align:left;font-size:14px}.member-list>button:hover{background:var(--input)}small{display:block;color:var(--muted);font-size:12px;line-height:18px;margin-top:2px}h3{font-size:14px;margin:32px 0 12px;font-weight:600}.invitation-row,.leave-row{border:1px solid var(--border);border-radius:8px;padding:16px;display:flex;align-items:center;gap:16px;font-size:13px}.invitation-row>span,.leave-row p{flex:1;overflow-wrap:anywhere}.invitation-row+.invitation-row{margin-top:8px}.member-dialog{padding:24px;display:grid;gap:20px}.member-dialog header{display:flex;justify-content:space-between;align-items:center}.member-dialog h2{font-size:18px;font-weight:600}.member-dialog p{font-size:14px;color:var(--muted);line-height:22px;overflow-wrap:anywhere}.member-dialog label{display:grid;gap:6px;font-size:14px}.member-dialog input,.member-dialog textarea,.member-dialog select{width:100%;padding:8px 10px;border:1px solid var(--border);border-radius:6px;background:var(--surface);font:inherit}.member-dialog footer{display:flex;justify-content:flex-end;gap:8px}.member-dialog textarea{min-height:80px}
</style>

<style scoped>
.colleagues-page{flex:1;min-height:0;overflow:auto;scrollbar-width:thin}.colleagues-page .members-intro{margin:-4px 20px 24px;display:block}.colleagues-page .members-intro p{line-height:normal}.colleagues-page .members-intro>.button{position:absolute;right:20px;top:12px;font-size:14px}.colleagues-page .member-list{display:block;padding:0 28px}.colleagues-page .member-list>button{border:0;border-radius:0;padding:6px 0;min-width:0}.colleagues-page .member-list small{margin-top:4px;font-size:12px;line-height:normal}.colleagues-page h3,.colleagues-page>.muted{margin-left:28px;margin-right:28px}.colleagues-page .invitation-row,.colleagues-page .leave-row{margin-left:28px;margin-right:28px;max-width:856px}.colleagues-page .small-empty{display:flex;flex-direction:column;align-items:center;gap:12px;padding:48px;color:var(--muted)}
</style>
